@startuml

class Line {
  + Name
}

class Piece {
  + Type
  + Reference
  + SellingPrice
}

class Component {
  + Code
  + ManufacturingPrice
  + Type
}

class PieceComponent {
  + Quantity
}

class Store {
  + Name
  + Address
  + FaxNumber
}

class Order {
  + OrderNumber
  + Date
}

Line "1" -- "*" Piece
Piece "1" -- "*" PieceComponent
PieceComponent "*" -- "1" Component
Component "*" -- "*" Piece
Store "1" -- "*" Order
Order "1" -- "*" Piece
Order "1" -- "1" Store

@enduml

